function saveCfg() {
  if (NBV._applying) return;
  const sh = cfgCollectShared();
  try {
    localStorage.setItem('an3', JSON.stringify({ ...sh, i: $('cI').value, snd: soundOn, sb: $('dspSb').value }));
  } catch (e) {}
  NBV.cfg.saveShared(sh);
}
function loadCfg() {
  let own = {};
  try { own = JSON.parse(localStorage.getItem('an3')) || {}; } catch (e) {}
  const c = NBV.cfg.merge(own);
  if (c.i) $('cI').value = c.i;
  if (c.snd !== undefined) soundOn = c.snd;
  if (c.sb) $('dspSb').value = c.sb;
  NBV._applying = true;
  try { cfgApplyFields(c); } finally { NBV._applying = false; }
  // Los módulos FSUIPC y phpVMS los ejecuta el OPS Center (pestaña OCC);
  // aquí solo se configuran y se refleja su estado.
  dcLoad().then(u => { if ($('discordEn').checked) discordSetStatus(u ? 'Webhook activo (cifrado)' : '✗ Activo pero sin webhook guardado', !!u || false); });
  if ($('phpvmsEn').checked) phpvmsSetStatus('Activo en OPS Center', null);
  if ($('fsuipcEn').checked) fsuipcSetStatus('Gestionado por OPS Center — conectando…', null);
}
