let lastInfoResult = '';

async function sendInfo() {
  if (busy) return;
  const icao = $('inI').value.trim().toUpperCase(), type = $('inT').value;
  if (!icao) return;
  busy = true; $('inB').disabled = true; $('inB').textContent = 'SOLICITANDO...';
  ss('snd', `${type.toUpperCase()} ${icao}...`);
  try {
    let txt = '', ok = true;
    if (type === 'metar' || type === 'metar-hist') {
      try {
        const m = await NBV.wx.metar(icao, type === 'metar-hist' ? 3 : 1);
        const lines = m.split('\n').filter(l => l.trim());
        if (!lines.length) { txt = `No METAR available for ${icao}`; ok = false; }
        else txt = type === 'metar' ? lines[0] : `METAR HISTORICO ${icao} (${lines.length} obs):\n${lines.join('\n')}`;
      } catch (e) {
        txt = await hoppieInfo('METAR', icao);
        ok = !!txt; if (!ok) txt = `METAR no disponible (${e.message})`;
        if (type === 'metar' && ok) txt = txt.split('\n').filter(l => l.trim())[0] || txt;
      }
    } else if (type === 'taf') {
      try { txt = await NBV.wx.taf(icao); }
      catch (e) { txt = await hoppieInfo('TAF', icao); }
      ok = !!txt; if (!ok) txt = 'No TAF available';
    } else if (type === 'ivaoatis') {
      // IVAO publica el ATIS en el propio whazzup; Hoppie como respaldo
      txt = await ivaoAtis(icao);
      if (!txt) txt = await hoppieInfo('IVAOATIS', icao);
      ok = !!txt; if (!ok) txt = `Sin ATIS IVAO para ${icao}`;
    } else {
      let cleaned = await hoppieInfo('VATATIS', icao);
      if (cleaned.toUpperCase().includes('AVAILABLE ATIS FOR')) {
        const lines = cleaned.split('\n').map(l => l.trim()).filter(l => l && !l.toUpperCase().startsWith('AVAILABLE'));
        const target = ['APP', 'TWR', 'GND', 'DEP', 'ATIS'].map(p => lines.find(l => l.toUpperCase().includes(`-${p}`) || l.toUpperCase().endsWith(p))).find(Boolean) || lines[0];
        if (target) {
          ss('snd', `ATIS múltiple — solicitando ${target}...`);
          const t2 = await hoppieInfo('VATATIS', target);
          cleaned = t2 ? `[${target}]\n${t2}` : `Múltiples ATIS disponibles:\n${lines.join('\n')}\n\nSolicita el deseado (ej: ${lines[0]})`;
          if (!t2) ok = false;
        }
      }
      txt = cleaned; if (!txt) { ok = false; txt = `Sin ATIS VATSIM para ${icao}`; }
    }
    $('inR').style.display = 'block'; $('inRT').textContent = txt || '(vacío)';
    lastInfoResult = `${type.toUpperCase()} ${icao}: ${txt}`;
    const label = type === 'metar-hist' ? 'METAR HIST' : type.toUpperCase();
    addMsg('rx', { cls: 'in', type: 'INFO', badge: 'b-in', route: `SERVER → ${$('cS').value.toUpperCase()}`, body: `${label} ${icao}:\n${txt}`, time: ts(), st: ok ? '✓ OK' : '✗ Sin datos', ok });
    const wxs = type.startsWith('metar') ? NBV.wx.source('metar') : type === 'taf' ? NBV.wx.source('taf') : '';
    ss(ok ? 'ok' : 'err', ok ? `✓ ${label} ${icao}${wxs && wxs !== 'aviationweather.gov' ? ` (fuente secundaria: ${wxs})` : ''}` : `✗ ${label} ${icao}: sin datos`);
    if (ok) notifySound();
  } catch (e) { $('inR').style.display = 'block'; $('inRT').textContent = `Error: ${e.message}`; ss('err', `✗ ${e.message}`); errorSound(); }
  busy = false; $('inB').textContent = 'SOLICITAR'; updBtn();
}

