let streamActive = false;
let streamTimer = null;

function openStream() {
  streamActive = true;
  $('streamOverlay').classList.add('on');
  document.body.style.overflow = 'hidden';

  // Get active airport from config (callsign station field)
  const stationCs = ($('cS')?.value || '').trim().toUpperCase();
  const icao = stationCs.replace(/_.*/, ''); // LEMD_TWR → LEMD
  $('strIcao').textContent = icao.length === 4 ? icao : '----';

  refreshStream();
}

function closeStream() {
  streamActive = false;
  $('streamOverlay').classList.remove('on');
  document.body.style.overflow = '';
  if (streamTimer) { clearTimeout(streamTimer); streamTimer = null; }
}

async function refreshStream() {
  if (!streamActive) return;
  const icao = ($('cS')?.value || '').trim().toUpperCase().replace(/_.*/, '');
  if (icao.length === 4) $('strIcao').textContent = icao;
  if (icao.length === 4) {
    try {
      const m = await NBV.wx.metarLatest(icao);
      const wx = m ? parseMetarSummary(m) : {};
      let h = '';
      if (wx.wind) h += `<div class="str-wx-item"><div class="str-wx-val" style="color:var(--inf)">${esc(wx.wind)}</div><div class="str-wx-lbl">Viento</div></div>`;
      if (wx.vis) h += `<div class="str-wx-item"><div class="str-wx-val" style="color:${wx.visWarn ? 'var(--wrn)' : 'var(--ok)'}">${esc(wx.vis)}</div><div class="str-wx-lbl">Visibilidad</div></div>`;
      if (wx.qnh) h += `<div class="str-wx-item"><div class="str-wx-val" style="color:var(--tx1)">${esc(wx.qnh)}</div><div class="str-wx-lbl">QNH</div></div>`;
      if (wx.temp) h += `<div class="str-wx-item"><div class="str-wx-val" style="color:var(--cpdlc)">${esc(wx.temp)}</div><div class="str-wx-lbl">Temp</div></div>`;
      $('strWx').innerHTML = h;
    } catch (e) { $('strWx').innerHTML = ''; }
    const atis = await ivaoAtis(icao);
    $('strAtisBox').style.display = atis ? 'block' : 'none';
    if (atis) $('strAtis').textContent = atis;
  }
  try {
    const data = await NBV.ivao.get();
    const prefix = (localStorage.getItem('an_ops') && (JSON.parse(localStorage.getItem('an_ops')).a || 'NBV')) || 'NBV';
    renderStreamFlights(NBV.ivao.pilots(data).filter(p => safeStr(p.callsign).toUpperCase().startsWith(prefix.toUpperCase())));
  } catch (e) {
    $('strFlights').innerHTML = `<div class="str-empty">Error IVAO: ${esc(e.message)}</div>`;
  }
  if (streamActive) streamTimer = setTimeout(refreshStream, 20000);
}

function renderStreamFlights(flights) {
  if (!flights.length) { $('strFlights').innerHTML = `<div class="str-empty">✈ Sin vuelos NBV activos en IVAO</div>`; return; }
  let html = `<table class="str-tbl"><thead><tr><th>Callsign</th><th>ACFT</th><th>Ruta</th><th>Estado</th><th>ALT</th><th>GS</th><th>DIST</th><th>ETA</th></tr></thead><tbody>`;
  for (const p of flights) {
    const fp = p.flightPlan || {}, lt = p.lastTrack || {};
    const alt = Math.round(safeNum(lt.altitude)), gs = safeNum(lt.groundSpeed), state = mapState(safeStr(lt.state));
    const arr = NBV.ivao.arrOf(p) || '????';
    const e = lt.onGround ? { dist: null, eta: null } : etaInfo({ arrivalDist: lt.arrivalDistance, gs, lat: lt.latitude, lon: lt.longitude, arr });
    html += `<tr><td class="str-cs">${esc(p.callsign || '???')}</td><td>${esc(safeStr(fp.aircraftId) || '???')}</td><td>${esc(NBV.ivao.depOf(p) || '????')} → ${esc(arr)}</td>
      <td><span class="str-state st-${state.cls}">${state.label}</span></td><td>${alt > 0 ? (alt >= 18000 ? `FL${Math.round(alt / 100)}` : `${alt}ft`) : '—'}</td>
      <td>${gs > 0 ? gs + 'kt' : '—'}</td><td>${e.dist != null ? e.dist + 'nm' : '—'}</td><td>${e.eta || '—'}</td></tr>`;
  }
  $('strFlights').innerHTML = html + `</tbody></table>`;
}

