async function sendChunked(to, body, tag, btn) {
  if (!to) { ss('err', '✗ Indica callsign destino'); return false; }
  if (!body) { ss('err', '✗ Primero genera un resultado'); return false; }
  if (!$('cL').value.trim() || !$('cS').value.trim()) { ss('err', '✗ Configura logon y callsign'); return false; }
  if (btn) btn.textContent = 'Enviando…';
  const chunks = splitMsg(body, 480);
  let allOk = true;
  for (let i = 0; i < chunks.length; i++) {
    const pfx = chunks.length > 1 ? `[${i + 1}/${chunks.length}] ` : '';
    try {
      const raw = await hReq(to, 'telex', pfx + chunks[i]);
      if (!hoppieOk(raw)) { allOk = false; ss('err', `✗ ${raw}`); break; }
      addMsg('tx', { cls: 'out', type: 'TELEX', badge: 'b-tx', route: `${$('cS').value.toUpperCase()} → ${to}`, body: `[${tag}] ${pfx}${chunks[i]}`, time: ts(), st: '✓ OK', ok: true });
      if (i < chunks.length - 1) await sleep(400);
    } catch (e) { allOk = false; ss('err', `✗ ${e.message}`); break; }
  }
  if (btn) {
    if (allOk) { btn.textContent = '✓ Enviado'; btn.className = 'dsp-send sent'; ss('ok', `✓ TELEX → ${to}`); }
    else { btn.textContent = '✗ Error'; btn.className = 'dsp-send fail'; errorSound(); setTimeout(() => { btn.textContent = 'Enviar TELEX'; btn.className = 'dsp-send'; }, 2000); }
  }
  return allOk;
}

