let hpTimer = null, hpSeq = 0, hpForce = false;

function uiHoppieCheck(delay = 700, force = false) { clearTimeout(hpTimer); hpForce = hpForce || force; hpTimer = setTimeout(uiHoppieRun, delay); }

async function uiHoppieRun() {
  const box = $('hpStatus'), cp = $('p-cpdlc').classList.contains('on');
  const dest = (cp ? $('cpD') : $('txD')).value.trim().toUpperCase(), st = $('cS').value.trim().toUpperCase();
  const force = hpForce; hpForce = false;
  if (dest.length < 3 || !st) { box.hidden = true; return; }
  const seq = ++hpSeq;
  box.hidden = false; box.className = 'hp chk'; box.innerHTML = `<i></i><div><span>Comprobando ${esc(dest)} en Hoppie…</span></div>`;
  let r;
  try { r = await NBV.hoppie.check(dest, st, force); }
  catch (e) { if (seq === hpSeq) { box.className = 'hp unk'; box.innerHTML = `<i></i><div><span>No se pudo consultar el estado en Hoppie (${esc(e.message)})</span></div>`; } return; }
  if (seq !== hpSeq) return;
  const L = []; let cls = 'ok';
  if (r.destOnline) L.push(`<b>${esc(dest)}</b> conectado a Hoppie (${esc(r.net)}, desde hace ${esc(uiAgo(r.destAgo))})`);
  else if (r.destOtherNets.length) { cls = 'err'; L.push(`<b>${esc(dest)}</b> está en ${esc(r.destOtherNets.join('/'))} y tu estación en ${esc(r.net)}: no recibirá. Usa el mismo código Hoppie, o la misma red en «My ACARS Account».`); }
  else { cls = 'wrn'; L.push(`<b>${esc(dest)}</b> no está conectado a Hoppie. Los mensajes quedan en cola 24 h y le llegarán cuando el avión haga su primera petición (ATIS, METAR o LOGON).`); }
  if (!r.stationOnline) { if (cls === 'ok') cls = 'wrn'; L.push(`Tu estación <b>${esc(st)}</b> no aparece conectada: activa la recepción automática para recibir respuestas y LOGON CPDLC.`); }
  if (r.pending.length) L.push(`<b>${r.pending.length}</b> pendiente${r.pending.length > 1 ? 's' : ''} de entregar · ${r.delivered} entregado${r.delivered === 1 ? '' : 's'} (24 h)`);
  else if (r.delivered) L.push(`Todo entregado: ${r.delivered} mensaje${r.delivered === 1 ? '' : 's'} en 24 h`);
  box.className = 'hp ' + cls;
  box.innerHTML = `<i></i><div>${L.map(l => `<span>${l}</span>`).join('')}</div><button type="button" class="ib" data-click="uiHoppieCheck|#0|$true" title="Volver a comprobar" aria-label="Volver a comprobar">${NBV.ui.icon('refresh')}</button>`;
}

function uiHoppieInit() {
  ['txD', 'cpD'].forEach(id => $(id).addEventListener('input', () => uiHoppieCheck(900)));
  document.querySelectorAll('.composer .tab').forEach(t => t.addEventListener('click', () => uiHoppieCheck(100)));
  setInterval(() => { if (!$('hpStatus').hidden && !document.hidden) uiHoppieRun(); }, 60000);
}

function uiAgo(t) { return String(t || '').replace(/\bdys?\b/g, 'd').replace(/\bhrs?\b/g, 'h').replace(/\bmns?\b/g, 'min').replace(/,/g, ''); }

