const CPK = 'nbv_cpdlc';

const CP_OK = ['WILCO', 'ROGER', 'AFFIRM'], CP_NO = ['UNABLE', 'NEGATIVE'];

function uiCpLoad() { try { return JSON.parse(localStorage.getItem(CPK)) || []; } catch (e) { return []; } }

function uiCpSave(l) { l = l.filter(x => Date.now() - x.t < 864e5).slice(-40); try { localStorage.setItem(CPK, JSON.stringify(l)); } catch (e) {} uiCpRender(); }

function uiCpdlcRef(to) {
  const r = uiCpLoad().filter(x => x.dir === 'down' && x.from === String(to).toUpperCase() && x.st === 'PENDIENTE').pop();
  return r ? String(r.mid) : '';
}

function uiCpdlcSent(to, mid, resp, msg, ref) {
  const l = uiCpLoad(); to = String(to).toUpperCase();
  l.push({ dir: 'up', to, mid: +mid, resp, msg, ref: ref ? +ref : null, t: Date.now(), st: resp === 'NE' || resp === 'N' ? 'INFO' : 'ABIERTO' });
  if (ref) l.forEach(x => { if (x.dir === 'down' && x.from === to && x.mid === +ref) x.st = 'RESPONDIDA'; });
  uiCpSave(l);
}

function uiCpdlcReply(sender, content) {
  const m = String(content || '').match(/^\/data2\/(\d+)\/(\d*)\/([A-Z]{1,2})\/([\s\S]*)$/);
  if (!m) return content;
  const [, mid, ref, rt, text] = m, from = String(sender).toUpperCase(), l = uiCpLoad();
  const up = ref ? [...l].reverse().find(x => x.dir === 'up' && x.to === from && x.mid === +ref) : null;
  if (up) {
    const w = (text.match(/\b(WILCO|UNABLE|STANDBY|ROGER|AFFIRM|NEGATIVE)\b/) || [])[1];
    if (w && !(w === 'STANDBY' && up.st !== 'ABIERTO')) up.st = w;
    uiCpSave(l);
    return `${text}\n↳ respuesta a #${ref}: ${up.msg}`;
  }
  l.push({ dir: 'down', from, mid: +mid, msg: text.trim(), t: Date.now(), st: /^(N|NE)$/.test(rt) || /^(WILCO|UNABLE|STANDBY|ROGER|AFFIRM|NEGATIVE)\b/.test(text) ? 'INFO' : 'PENDIENTE' });
  uiCpSave(l);
  return `${text}${ref ? '' : `\n(petición #${mid} — tu próximo CPDLC a ${from} la responderá)`}`;
}

