function uiCpRender() {
  const box = $('cpLog'); if (!box) return;
  const l = uiCpLoad().slice(-12).reverse();
  const cls = st => CP_OK.includes(st) ? 'ok' : CP_NO.includes(st) ? 'err' : st === 'ABIERTO' || st === 'PENDIENTE' ? 'wrn' : st === 'STANDBY' ? 'inf' : '';
  const hh = t => new Date(t).toISOString().slice(11, 16) + 'z';
  box.innerHTML = l.length ? `<div class="cmp-lbl">Diálogo CPDLC <button type="button" class="sm" data-click="uiCpClear">Vaciar</button></div>` + l.map(x => x.dir === 'up'
    ? `<div class="cp-row"><span class="cp-d" title="Enviado">↑</span><div><b>${esc(x.to)}</b> <small>#${esc(x.mid)} · ${hh(x.t)}</small><div class="cp-m">${esc(x.msg)}</div></div><span class="cp-st ${cls(x.st)}">${esc(x.st)}</span></div>`
    : `<div class="cp-row${x.st === 'PENDIENTE' ? ' act' : ''}"${x.st === 'PENDIENTE' ? ` role="button" tabindex="0" title="Responder" data-click="uiCpReply|${esc(x.from)}"` : ''}><span class="cp-d" title="Recibido">↓</span><div><b>${esc(x.from)}</b> <small>#${esc(x.mid)} · ${hh(x.t)}</small><div class="cp-m">${esc(x.msg)}</div></div><span class="cp-st ${cls(x.st)}">${esc(x.st)}</span></div>`).join('') : '';
}

const uiDel = new Map();

let uiDelT = null;

const uiNorm = s => String(s || '').replace(/\s+/g, ' ').trim().toUpperCase();

function uiDeliveryWatch(dest) {
  dest = String(dest || '').trim().toUpperCase(); if (dest.length < 3) return;
  const e = uiDel.get(dest) || { since: Date.now(), notified: new Set(), init: false };
  e.until = Date.now() + 2 * 3600e3; uiDel.set(dest, e);
  clearTimeout(uiDelT); uiDelT = setTimeout(uiDeliveryRun, 8000);
}

function uiRxTime(s) { // "02-16:38Z" → ms UTC
  const m = String(s).match(/(\d{2})-(\d{2}):(\d{2})/); if (!m) return 0;
  const n = new Date(); let t = Date.UTC(n.getUTCFullYear(), n.getUTCMonth(), +m[1], +m[2], +m[3]);
  if (t > Date.now() + 864e5) t = Date.UTC(n.getUTCFullYear(), n.getUTCMonth() - 1, +m[1], +m[2], +m[3]);
  return t;
}

async function uiDeliveryRun() {
  clearTimeout(uiDelT);
  const st = $('cS').value.trim().toUpperCase(); if (!st || !uiDel.size) return;
  let net = 'IVAO'; try { net = ((await NBV.hoppie.online()).get(st) || [])[0]?.net || net; } catch (e) {}
  let waiting = false;
  for (const [dest, e] of uiDel) {
    if (Date.now() > e.until) { uiDel.delete(dest); continue; }
    let h; try { h = await NBV.hoppie.history(dest, net); } catch (err) { waiting = true; continue; }
    const mine = h.filter(x => x.from === st && x.to === dest && uiRxTime(x.rx) >= e.since - 180000);
    const fresh = mine.filter(x => x.relayed && !e.notified.has(x.id));
    fresh.forEach(x => { e.notified.add(x.id); uiMarkDelivered(dest, x); });
    if (fresh.length && e.init) { NBV.sound.play('delivered'); ss('ok', `✓ ${dest} ha recibido ${fresh.length} mensaje${fresh.length > 1 ? 's' : ''} (${fresh.at(-1).relayed})`); }
    else if (fresh.length) { e.init = true; } // entregados antes de la primera comprobación: se marcan sin aviso
    e.init = true;
    if (mine.some(x => !x.relayed)) waiting = true; else if (Date.now() - e.since > 600000) uiDel.delete(dest);
  }
  if (!$('hpStatus').hidden) uiHoppieRun();
  if (waiting || uiDel.size) uiDelT = setTimeout(uiDeliveryRun, waiting ? 45000 : 90000);
}

function uiMarkDelivered(dest, x) {
  let key = x.type === 'cpdlc' ? x.text.split('/').slice(4).join('/') : x.text;
  key = uiNorm(key).slice(0, 20);
  for (const el of $('txL').querySelectorAll('.me')) {
    if (el.dataset.dlv) continue;
    if (!(el.querySelector('.mr')?.textContent || '').trim().endsWith(dest)) continue;
    const b = uiNorm(el.querySelector('.mb')?.textContent || '').replace(/^\[[A-Z]{1,2}\] /, '');
    if (key && !b.includes(key.slice(0, 14))) continue;
    el.dataset.dlv = '1';
    const ms = el.querySelector('.ms'); if (ms) ms.textContent += ` · Entregado ${x.relayed}`;
    saveList('tx'); return true;
  }
  return false;
}

