function setStatus(msg, cls = '') { const el = $('setStatus'); if (!el) return; el.textContent = msg; el.className = 'cfg-mod-status' + (cls ? ' ' + cls : ''); }
function setRenderBackup() { const b = $('setRestoreBtn'); if (b) b.hidden = !NBV.settings.hasBackup(); }
function setExport() {
  const d = NBV.settings.export(), n = Object.keys(d.keys).length;
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([JSON.stringify(d, null, 1)], { type: 'application/json' }));
  a.download = `nbv-ajustes-${d.version}-${d.exported.slice(0, 10)}.json`;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
  setStatus(`Exportados ${n} grupos de ajustes, sin credenciales`, 'ok');
}
function setImportPick() { const f = $('setFile'); f.value = ''; f.click(); }
async function setImportFile(el) {
  const file = el.files && el.files[0];
  if (!file) return;
  const text = await file.text();
  const v = NBV.settings.validate(text);
  if (!v.ok) { setStatus(`No se ha importado nada: ${v.error}`, 'err'); NBV.security.event('ajustes-rechazados', v.error); return; }
  const n = Object.keys(v.keys).length;
  if (!confirm(`¿Importar ${n} grupos de ajustes (v${v.version}, ${String(v.exported || '').slice(0, 10)})?\n\nSustituyen a los actuales; antes se guarda una copia para poder deshacerlo. Tu logon de Hoppie y las credenciales de este equipo no cambian. La página se recargará.`)) { setStatus('Importación cancelada'); return; }
  // Revisión 5.1 #2: direcciones de red distintas → segunda confirmación expresa (por defecto se mantienen las de este equipo)
  let acceptUrls = false;
  if (v.urlChanges.length) {
    const list = v.urlChanges.map(c => `· ${c.label}: ${c.from || '(por defecto)'} → ${c.to || '(por defecto)'}`).join('\n');
    acceptUrls = confirm(`El fichero trae direcciones de red distintas de las de este equipo:\n\n${list}\n\nLa API key de phpVMS se envía a esa dirección y todo el tráfico pasa por el proxy. Acepta solo si el fichero es tuyo.\n\nAceptar = usar las del fichero · Cancelar = mantener las de este equipo (recomendado si dudas)`);
  }
  const r = NBV.settings.apply(text, { acceptUrls });
  if (!r.ok) { setStatus(`No se ha importado nada: ${r.error}`, 'err'); return; }
  setStatus(`Importados ${r.applied.length} grupos de ajustes${v.urlChanges.length ? (acceptUrls ? ', con las direcciones del fichero' : ', manteniendo las direcciones de red de este equipo') : ''}. Recargando…`, 'ok');
  setTimeout(() => location.reload(), 600);
}
function setRestore() {
  if (!confirm('¿Volver a los ajustes de antes de la última importación? La página se recargará.')) return;
  if (NBV.settings.restore()) { setStatus('Ajustes anteriores restaurados. Recargando…', 'ok'); setTimeout(() => location.reload(), 600); }
  else setStatus('No hay copia previa que restaurar', 'err');
}
